// Remap (u, v) to [-1, 1]^2
    Point2f uOffset = 2.f * u - Point2f(1, 1);

    // Handle degeneracy at the origin
    if (uOffset.x == 0 && uOffset.y == 0)
        return Point2f(0, 0);

    // Apply concentric mapping to point
    float theta, r;
    if (std::abs(uOffset.x) > std::abs(uOffset.y)) {
        r = uOffset.x;
        theta = (std::numbers::pi_v<float> / 4) * (uOffset.y / uOffset.x);
    } else {
        r = uOffset.y;
        theta = (std::numbers::pi_v<float> / 2) - (std::numbers::pi_v<float> / 4) * (uOffset.x / uOffset.y);
    }
    return Point2f(r * std::cos(theta), r * std::sin(theta));
// END_CODE

